CREATE TABLE public.siddi_owner_setup (id boolean PRIMARY KEY DEFAULT true CHECK(id), owner_email text NOT NULL, owner_user_id uuid, completed_at timestamptz);
GRANT ALL ON public.siddi_owner_setup TO service_role;
ALTER TABLE public.siddi_owner_setup ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.admin_permissions (user_id uuid PRIMARY KEY, is_super_admin boolean NOT NULL DEFAULT false, can_manage_admins boolean NOT NULL DEFAULT false, created_by uuid, updated_by uuid, updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.admin_permissions TO authenticated;
GRANT ALL ON public.admin_permissions TO service_role;
ALTER TABLE public.admin_permissions ENABLE ROW LEVEL SECURITY;
CREATE POLICY "own admin permissions" ON public.admin_permissions FOR SELECT TO authenticated USING(user_id=auth.uid());
ALTER TABLE public.staff_profiles ADD COLUMN IF NOT EXISTS active boolean NOT NULL DEFAULT true, ADD COLUMN IF NOT EXISTS team_ids uuid[] NOT NULL DEFAULT '{}', ADD COLUMN IF NOT EXISTS corporations text[] NOT NULL DEFAULT '{}', ADD COLUMN IF NOT EXISTS created_by uuid, ADD COLUMN IF NOT EXISTS updated_by uuid;
CREATE OR REPLACE FUNCTION public.account_active(_user uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM auth.users u WHERE u.id=_user AND (u.banned_until IS NULL OR u.banned_until<=now())) AND coalesce((SELECT active FROM public.staff_profiles WHERE user_id=_user),true) $$;
REVOKE ALL ON FUNCTION public.account_active(uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.account_active(uuid) TO authenticated,service_role;
CREATE OR REPLACE FUNCTION public.has_role(_user_id uuid,_role public.app_role) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.account_active(_user_id) AND EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=_user_id AND role=_role) $$;
CREATE OR REPLACE FUNCTION public.is_staff(_user_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.account_active(_user_id) AND EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=_user_id AND role::text IN ('admin','staff','supervisor','field_worker')) $$;
CREATE OR REPLACE FUNCTION public.is_supervisor(_user_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.account_active(_user_id) AND EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=_user_id AND role::text IN ('admin','staff','supervisor')) $$;
CREATE OR REPLACE FUNCTION public.can_manage_admins(_user uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.has_role(_user,'admin') AND EXISTS(SELECT 1 FROM public.admin_permissions WHERE user_id=_user AND (is_super_admin OR can_manage_admins)) $$;
REVOKE ALL ON FUNCTION public.can_manage_admins(uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.can_manage_admins(uuid) TO authenticated,service_role;
CREATE OR REPLACE FUNCTION public.handle_first_admin() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN RETURN NEW; END $$;
CREATE OR REPLACE FUNCTION public.complete_siddi_owner_setup(_user uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE s public.siddi_owner_setup; e text;
BEGIN
 SELECT * INTO s FROM public.siddi_owner_setup WHERE id=true FOR UPDATE;
 IF s.owner_email IS NULL OR s.completed_at IS NOT NULL THEN RAISE EXCEPTION 'Owner setup unavailable or already completed'; END IF;
 SELECT lower(email) INTO e FROM auth.users WHERE id=_user;
 IF e IS DISTINCT FROM lower(s.owner_email) THEN RAISE EXCEPTION 'Owner identity does not match'; END IF;
 INSERT INTO public.user_roles(user_id,role) VALUES(_user,'admin') ON CONFLICT DO NOTHING;
 INSERT INTO public.admin_permissions(user_id,is_super_admin,can_manage_admins) VALUES(_user,true,true);
 INSERT INTO public.staff_profiles(user_id,display_name,designation,department) VALUES(_user,'Siddi owner','Super Admin','Siddi administration') ON CONFLICT DO NOTHING;
 UPDATE public.siddi_owner_setup SET owner_user_id=_user,completed_at=now() WHERE id=true;
 INSERT INTO public.civic_directory_audit(table_name,record_id,action,actor_id,new_row) VALUES('administrator_accounts',_user,'owner_provisioned',_user,jsonb_build_object('role','super_admin'));
END $$;
REVOKE ALL ON FUNCTION public.complete_siddi_owner_setup(uuid) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.complete_siddi_owner_setup(uuid) TO service_role;
CREATE OR REPLACE FUNCTION public.staff_scope_matches(_department text,_categories text[],_wards text[],_teams uuid[],_corporations text[],_category text,_case_department text,_team uuid,_ward text,_corporation text) RETURNS boolean LANGUAGE sql IMMUTABLE AS $$ SELECT coalesce(length(trim(_department))>0 AND cardinality(_categories)>0 AND _category=ANY(_categories) AND _department=_case_department AND (cardinality(_teams)=0 OR _team=ANY(_teams)) AND (cardinality(_wards)=0 OR _ward=ANY(_wards)) AND (cardinality(_corporations)=0 OR _corporation=ANY(_corporations)),false) $$;
REVOKE ALL ON FUNCTION public.staff_scope_matches(text,text[],text[],uuid[],text[],text,text,uuid,text,text) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.staff_scope_matches(text,text[],text[],uuid[],text[],text,text,uuid,text,text) TO authenticated,service_role;
CREATE OR REPLACE FUNCTION public.staff_can_work(_user_id uuid,_issue uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.is_staff(_user_id) AND (public.has_role(_user_id,'admin') OR EXISTS(SELECT 1 FROM public.issues i JOIN public.staff_profiles p ON p.user_id=_user_id LEFT JOIN public.civic_teams t ON t.id=i.team_id WHERE i.id=_issue AND p.active AND public.staff_scope_matches(p.department,p.categories,p.wards,p.team_ids,p.corporations,i.category,coalesce(t.department,i.department),i.team_id,i.routing_snapshot->'ward'->>'identifier',i.routing_snapshot->'ward'->>'corporation'))) $$;
ALTER POLICY "staff case reads" ON public.issues USING(public.staff_can_work(auth.uid(),id));
ALTER POLICY "staff read notifications" ON public.issue_notifications USING(public.staff_can_work(auth.uid(),issue_id));
ALTER POLICY "staff read staff profiles" ON public.staff_profiles USING(user_id=auth.uid() OR public.has_role(auth.uid(),'admin'));
DO $$ DECLARE r record; col text; BEGIN FOR r IN SELECT tablename,policyname FROM pg_policies WHERE schemaname='public' AND tablename IN ('issue_events','issue_evidence','issue_photos','issue_assignments','issue_ownership_reviews','issue_duplicate_reviews') AND cmd='SELECT' LOOP col:=CASE WHEN r.tablename='issue_duplicate_reviews' THEN 'report_id' ELSE 'issue_id' END; EXECUTE format('ALTER POLICY %I ON public.%I USING (public.staff_can_work(auth.uid(),%I))',r.policyname,r.tablename,col); END LOOP; END $$;
DO $$ DECLARE d text; r record; guard text; BEGIN FOR r IN SELECT p.oid,p.proname FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='public' AND p.proname IN ('assign_civic_issue','review_issue_duplicate','staff_edit_classification','staff_record_evidence') LOOP d:=pg_get_functiondef(r.oid); guard:=CASE WHEN r.proname='review_issue_duplicate' THEN 'IF NOT public.is_supervisor(auth.uid()) OR NOT public.staff_can_work(auth.uid(),_report) OR NOT public.staff_can_work(auth.uid(),_candidate) THEN RAISE EXCEPTION ''Case review outside authorized scope''; END IF;' WHEN r.proname IN ('assign_civic_issue','staff_edit_classification') THEN 'IF NOT public.is_supervisor(auth.uid()) OR NOT public.staff_can_work(auth.uid(),_id) THEN RAISE EXCEPTION ''Case correction outside authorized scope''; END IF;' ELSE 'IF NOT public.staff_can_work(auth.uid(),_id) THEN RAISE EXCEPTION ''Evidence outside authorized scope''; END IF;' END; d:=regexp_replace(d,'BEGIN','BEGIN '||guard); EXECUTE d; END LOOP; END $$;
CREATE OR REPLACE FUNCTION public.staff_assign_team(_issue uuid,_team uuid,_reason text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE t public.civic_teams; i public.issues; p public.staff_profiles; BEGIN IF NOT public.is_supervisor(auth.uid()) OR NOT public.staff_can_work(auth.uid(),_issue) THEN RAISE EXCEPTION 'Assignment outside authorized scope'; END IF; SELECT * INTO i FROM public.issues WHERE id=_issue FOR UPDATE; SELECT * INTO t FROM public.civic_teams WHERE id=_team AND active; IF t.id IS NULL OR length(trim(_reason))<3 THEN RAISE EXCEPTION 'Active team and reason required'; END IF; IF NOT i.category=ANY(t.categories) OR (cardinality(t.wards)>0 AND NOT coalesce(i.routing_snapshot->'ward'->>'identifier'=ANY(t.wards),false)) THEN RAISE EXCEPTION 'Team does not support this case'; END IF; IF NOT public.has_role(auth.uid(),'admin') THEN SELECT * INTO p FROM public.staff_profiles WHERE user_id=auth.uid(); IF p.department<>t.department OR (cardinality(p.team_ids)>0 AND NOT t.id=ANY(p.team_ids)) THEN RAISE EXCEPTION 'Target team outside authorized scope'; END IF; END IF; UPDATE public.issues SET team_id=_team,department=t.department,assigned_to=NULL,assignment_state='assigned',updated_at=now() WHERE id=_issue; INSERT INTO public.issue_events(issue_id,kind,note,actor_id,actor_label) VALUES(_issue,'assignment','Assigned to '||t.name||'. '||_reason,auth.uid(),public.staff_actor_label(auth.uid())); END $$;
CREATE OR REPLACE FUNCTION public.admin_set_account_state(_user uuid,_active boolean,_reason text) RETURNS integer LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE n integer; BEGIN IF NOT public.has_role(auth.uid(),'admin') OR _user=auth.uid() OR length(trim(_reason))<3 THEN RAISE EXCEPTION 'Account change not permitted'; END IF; IF EXISTS(SELECT 1 FROM public.admin_permissions WHERE user_id=_user AND is_super_admin) THEN RAISE EXCEPTION 'Super Admin cannot be suspended'; END IF; IF EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=_user AND role='admin') AND NOT public.can_manage_admins(auth.uid()) THEN RAISE EXCEPTION 'Administrator management permission required'; END IF; INSERT INTO public.staff_profiles(user_id,active,updated_by) VALUES(_user,_active,auth.uid()) ON CONFLICT(user_id) DO UPDATE SET active=excluded.active,updated_by=auth.uid(),updated_at=now(); SELECT count(*) INTO n FROM public.issues WHERE assigned_to=_user AND status::text NOT IN ('resolved','closed','rejected'); IF NOT _active THEN UPDATE public.issues SET assigned_to=NULL,updated_at=now() WHERE assigned_to=_user AND status::text NOT IN ('resolved','closed','rejected'); END IF; INSERT INTO public.civic_directory_audit(table_name,record_id,action,actor_id,new_row) VALUES('staff_accounts',_user,CASE WHEN _active THEN 'reactivate' ELSE 'suspend' END,auth.uid(),jsonb_build_object('reason',_reason,'reassignment_required',n)); RETURN n; END $$;
REVOKE ALL ON FUNCTION public.admin_set_account_state(uuid,boolean,text) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.admin_set_account_state(uuid,boolean,text) TO authenticated;
CREATE OR REPLACE FUNCTION public.admin_set_delegation(_user uuid,_allow boolean) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.has_role(auth.uid(),'admin') OR NOT EXISTS(SELECT 1 FROM public.admin_permissions WHERE user_id=auth.uid() AND is_super_admin) THEN RAISE EXCEPTION 'Only Super Admin can delegate administrator creation'; END IF; IF NOT public.has_role(_user,'admin') OR EXISTS(SELECT 1 FROM public.admin_permissions WHERE user_id=_user AND is_super_admin) THEN RAISE EXCEPTION 'Select an additional administrator'; END IF; INSERT INTO public.admin_permissions(user_id,can_manage_admins,created_by,updated_by) VALUES(_user,_allow,auth.uid(),auth.uid()) ON CONFLICT(user_id) DO UPDATE SET can_manage_admins=_allow,updated_by=auth.uid(),updated_at=now(); INSERT INTO public.civic_directory_audit(table_name,record_id,action,actor_id,new_row) VALUES('administrator_accounts',_user,'delegation_changed',auth.uid(),jsonb_build_object('can_manage_admins',_allow)); END $$;
REVOKE ALL ON FUNCTION public.admin_set_delegation(uuid,boolean) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.admin_set_delegation(uuid,boolean) TO authenticated;
CREATE OR REPLACE FUNCTION public.staff_queue_issues(_category text DEFAULT NULL,_status text DEFAULT NULL,_severity text DEFAULT NULL,_ward text DEFAULT NULL,_team uuid DEFAULT NULL,_ack text DEFAULT NULL,_overdue boolean DEFAULT NULL,_search text DEFAULT NULL,_limit integer DEFAULT 500) RETURNS TABLE(id uuid,ref_code text,title text,category text,severity issue_severity,status issue_status,sla_due_at timestamptz,eta_at timestamptz,acknowledged_at timestamptz,escalated_at timestamptz,created_at timestamptz,landmark text,department text,support_count integer,photo_url text,authority_id uuid,assignment_state text,duplicate_of uuid,duplicate_candidate_id uuid,team_id uuid,team_name text,ward_name text) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT i.id,i.ref_code,i.title,i.category,i.severity,i.status,i.sla_due_at,i.eta_at,i.acknowledged_at,i.escalated_at,i.created_at,i.landmark,i.department,i.support_count,i.photo_url,i.authority_id,i.assignment_state,i.duplicate_of,i.duplicate_candidate_id,i.team_id,t.name,i.routing_snapshot->'ward'->>'name' FROM public.issues i LEFT JOIN public.civic_teams t ON t.id=i.team_id WHERE public.staff_can_work(auth.uid(),i.id) AND (_category IS NULL OR i.category=_category) AND (_status IS NULL OR i.status::text=_status) AND (_severity IS NULL OR i.severity::text=_severity) AND (_ward IS NULL OR i.routing_snapshot->'ward'->>'identifier'=_ward) AND (_team IS NULL OR i.team_id=_team) AND (_ack IS NULL OR (_ack='acknowledged' AND i.acknowledged_at IS NOT NULL) OR (_ack='unacknowledged' AND i.acknowledged_at IS NULL)) AND (_overdue IS NULL OR (_overdue AND i.sla_due_at<now() AND i.status::text NOT IN ('resolved','closed','rejected'))) AND (_search IS NULL OR (i.title||' '||i.ref_code||' '||coalesce(i.landmark,'')) ILIKE '%'||_search||'%') ORDER BY i.created_at DESC LIMIT least(greatest(_limit,1),1000) $$;